import { oauthProviderAuthServerMetadata } from '@better-auth/oauth-provider'
import { metadataCorsOptionsRequestHandler } from 'mcp-handler'
import { auth } from '@/lib/auth'

/**
 * RFC 8414 metadata for the OAuth server in lib/auth.ts. Its issuer is
 * <origin>/mikka/api/auth, so clients look for
 * /.well-known/oauth-authorization-server/mikka/api/auth at the origin's root;
 * next.config.mjs redirects that path here.
 */
export const GET = oauthProviderAuthServerMetadata(auth, { headers: { 'Access-Control-Allow-Origin': '*' } })

export const OPTIONS = metadataCorsOptionsRequestHandler()

import { generateProtectedResourceMetadata, getPublicOrigin, metadataCorsOptionsRequestHandler } from 'mcp-handler'
import { withBasePath } from '@/lib/base-path'
import { appOrigin, MCP_SCOPE } from '@/lib/mcp/resource'

/**
 * RFC 9728 metadata for the MCP server at /api/mcp: which authorization
 * server signs agents in. The MCP server's 401 points here; the RFC's
 * root path (/.well-known/oauth-protected-resource/mikka/api/mcp) is
 * redirected here in next.config.mjs.
 */
export function GET(request: Request) {
  const origin = appOrigin ?? getPublicOrigin(request)
  const metadata = generateProtectedResourceMetadata({
    authServerUrls: [`${origin}${withBasePath('/api/auth')}`],
    resourceUrl: `${origin}${withBasePath('/api/mcp')}`,
    additionalMetadata: { scopes_supported: [MCP_SCOPE, 'offline_access'], resource_name: 'Mikka' },
  })
  return Response.json(metadata, { headers: { 'Access-Control-Allow-Origin': '*', 'Cache-Control': 'max-age=3600' } })
}

export const OPTIONS = metadataCorsOptionsRequestHandler()

import { noteLogUser, withRequestLog } from '@/lib/request-log'
import { randomBytes, randomUUID } from 'node:crypto'
import { NextRequest, NextResponse } from 'next/server'
import { auth } from '@/lib/auth'
import { isAcceptanceEnabled } from '@/lib/acceptance'
import { withBasePath } from '@/lib/base-path'

export const dynamic = 'force-dynamic'

function redirectWithinPreview(path: '/' | '/?acceptance=1' | '/acceptance') {
  // NextRequest.url can contain the internal 0.0.0.0 origin behind the preview proxy.
  return new NextResponse(null, { status: 307, headers: { Location: withBasePath(path), 'Cache-Control': 'no-store' } })
}

async function handleGET(request: NextRequest) {
  if (!isAcceptanceEnabled()) return new NextResponse(null, { status: 404 })

  try {
    const session = await auth.api.getSession({ headers: request.headers })
    noteLogUser(session?.user?.id)
    if (session?.user) return redirectWithinPreview('/')

    const result = await auth.api.signUpEmail({
      headers: request.headers,
      asResponse: true,
      body: {
        name: 'Acceptance Guest',
        email: `acceptance-${randomUUID()}@preview.mikka.invalid`,
        password: randomBytes(32).toString('base64url'),
      },
    })
    const cookies = result.headers.getSetCookie()
    if (!result.ok || cookies.length === 0) throw new Error('Acceptance session unavailable')

    const response = redirectWithinPreview('/?acceptance=1')
    for (const cookie of cookies) response.headers.append('Set-Cookie', cookie)
    return response
  } catch {
    console.error('Unable to start the development acceptance session')
    return redirectWithinPreview('/acceptance')
  }
}

export const GET = withRequestLog('/api/acceptance', handleGET)

import { freshSessionRoute } from '@/lib/fresh-session'
import { z } from 'zod'
import { auth } from '@/lib/auth'
import { GovernanceError } from '@/lib/governance/errors'
import { AccountAuthenticationError, requireFreshAccountSession } from '@/lib/account/fresh-session'
import { cancelAccountDeletion, readAccountDeletionReceipt, requestAccountDeletion } from '@/lib/account/deletion-jobs'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'
const headers = { 'cache-control': 'private, no-store', 'referrer-policy': 'no-referrer', 'x-content-type-options': 'nosniff' }
const receipt = z.string().uuid()
const requestBody = z.object({ email: z.string().trim().max(320), requestId: receipt }).strict()

/** A caller keeps its private request UUID before POST so a lost response can be resumed. No ID appears in a URL. */
async function POSTBody(request: Request) {
  if (request.headers.get('origin') !== new URL(request.url).origin) return Response.json({ error: 'originNotAllowed' }, { status: 403, headers })
  let session
  try { session = await requireFreshAccountSession(request.headers) }
  catch (error) {
    if (error instanceof AccountAuthenticationError) return Response.json({ error: error.code }, { status: error.status, headers })
    return Response.json({ error: 'accountDeletionUnavailable' }, { status: 503, headers })
  }
  const input = requestBody.safeParse(await request.json().catch(() => null))
  if (!input.success || input.data.email.toLowerCase() !== session.user.email.toLowerCase()) return Response.json({ error: 'accountEmailMismatch' }, { status: 400, headers })
  try {
    const job = await requestAccountDeletion(session.user.id, session.user.email, input.data.requestId)
    if (!job.ok) return Response.json({ error: 'accountSoleAdmin', workspaces: job.soleAdminOf }, { status: 409, headers })
    return Response.json(await readAccountDeletionReceipt(job.id), { status: 202, headers })
  } catch (error) {
    if (error instanceof GovernanceError && error.detail === 'last_owner') return Response.json({ error: 'accountLastOrganizationOwner' }, { status: 409, headers })
    return Response.json({ error: 'accountDeletionUnavailable' }, { status: 503, headers })
  }
}
/** Receipt capability remains usable when the account and its sessions have already been deleted. */
export async function GET(request: Request) {
  const input = receipt.safeParse(request.headers.get('x-mikka-deletion-receipt'))
  if (!input.success) return Response.json({ error: 'accountDeletionUnavailable' }, { status: 404, headers })
  try { return Response.json(await readAccountDeletionReceipt(input.data), { headers }) }
  catch { return Response.json({ error: 'accountDeletionUnavailable' }, { status: 404, headers }) }
}
async function DELETEBody(request: Request) {
  if (request.headers.get('origin') !== new URL(request.url).origin) return Response.json({ error: 'originNotAllowed' }, { status: 403, headers })
  const session = await auth.api.getSession({ headers: request.headers })
  if (!session?.user || !session.session) return Response.json({ error: 'authRequired' }, { status: 401, headers })
  const input = receipt.safeParse(request.headers.get('x-mikka-deletion-receipt'))
  if (!input.success) return Response.json({ error: 'accountDeletionUnavailable' }, { status: 404, headers })
  try {
    const cancelled = await cancelAccountDeletion(session.user.id, input.data)
    return Response.json({ cancelled }, { status: cancelled ? 200 : 409, headers })
  } catch { return Response.json({ error: 'accountDeletionUnavailable' }, { status: 404, headers }) }
}

// Credentials, permissions, money and deletion: the session is read from the database, not the cookie cache.
export const POST = freshSessionRoute(POSTBody)
export const DELETE = freshSessionRoute(DELETEBody)

import { auth } from '@/lib/auth'
import { buildAccountExport, claimExport } from '@/lib/account/export'
import { accountExportBody, accountExportFiles } from '@/lib/account/export-files'

export const dynamic = 'force-dynamic'

const privateHeaders = { 'cache-control': 'private, no-store', 'referrer-policy': 'no-referrer', 'x-content-type-options': 'nosniff' }

/**
 * `GET /api/account/export/:token`: the 「导出我的数据」 file the email links to.
 * It opens only for the signed-in account that asked for it and only until
 * the link expires (lib/account/export.ts); the file is built at download time.
 */
export async function GET(request: Request, { params }: { params: Promise<{ token: string }> }) {
  const session = await auth.api.getSession({ headers: request.headers, query: { disableCookieCache: true, disableRefresh: true } })
  if (!session?.user) return new Response('Sign in to Mikka with the account that asked for this export, then open the link again.', { status: 401, headers: privateHeaders })
  const { token } = await params
  if (!await claimExport(session.user.id, token)) return new Response('This export link has expired or belongs to another account.', { status: 404, headers: privateHeaders })
  const now = new Date()
  const data = await buildAccountExport(session.user.id, now)
  const files = await accountExportFiles(session.user.id)
  const assertCurrent = async () => {
    const current = await auth.api.getSession({ headers: request.headers, query: { disableCookieCache: true, disableRefresh: true } })
    if (current?.user.id !== session.user.id || !await claimExport(session.user.id, token)) throw new Error('Account export authorization expired')
  }
  return new Response(accountExportBody(data, files, session.user.id, { assertCurrent, signal: request.signal }), {
    headers: {
      ...privateHeaders,
      'content-type': 'application/json; charset=utf-8',
      'content-disposition': `attachment; filename="mikka-export-${now.toISOString().slice(0, 10)}.json"`,
      'content-security-policy': "sandbox; default-src 'none'",
    },
  })
}

import { z } from 'zod'
import { auth } from '@/lib/api-auth'
import { pool } from '@/lib/db'
import { readCliAgentPolicy, readCliRunPolicy } from '@/lib/agent-tool-approval/policy-store'
import { setCliAgentPolicy, setCliPolicy } from '@/lib/agent-tool-approval/policy-settings'
import { humanSessionHeaders } from '@/lib/desktop-rpc/handler'

export const dynamic = 'force-dynamic'
const schema = z.discriminatedUnion('operation', [
  z.object({ operation:z.literal('read'), runId:z.uuid() }).strict(),
  z.object({ operation:z.literal('readAgent'), agentId:z.uuid(), botId:z.uuid().nullable() }).strict(),
  z.object({ operation:z.literal('setAgent'), agentId:z.uuid(), botId:z.uuid().nullable(), target:z.enum(['agent','worker','workspace']), expectedRevision:z.string().regex(/^[a-f0-9]{64}$/), policy:z.unknown() }).strict(),
  z.object({ operation:z.literal('set'), runId:z.uuid(), target:z.enum(['agent','worker','workspace','team','project']), expectedRevision:z.string().regex(/^[a-f0-9]{64}$/), policy:z.unknown() }).strict(),
])
export async function POST(request: Request) {
  const sessionHeaders = humanSessionHeaders(request)
  if (!sessionHeaders || request.headers.get('origin') !== new URL(request.url).origin) return Response.json({ error:'unauthorized' }, { status:401 })
  const session = await auth.api.getSession({ headers:sessionHeaders, query:{ disableCookieCache:true } })
  if (!session?.user) return Response.json({ error:'unauthorized' }, { status:401 })
  const result = schema.safeParse(await request.json().catch(() => null))
  if (!result.success) return Response.json({ error:'invalidRequest' }, { status:400 })
  const body = result.data
  try {
    const value = body.operation === 'read' ? await readCliRunPolicy(pool,body.runId,session.user.id)
      : body.operation === 'set' ? await setCliPolicy(pool,session.user.id,body.runId,body.target,body.expectedRevision,body.policy)
      : body.operation === 'readAgent' ? await readCliAgentPolicy(pool,session.user.id,body.agentId,body.botId)
      : await setCliAgentPolicy(pool,session.user.id,body.agentId,body.botId,body.target,body.expectedRevision,body.policy)
    return Response.json(value, { headers:{ 'cache-control':'no-store' } })
  } catch { return Response.json({ error:'agentPolicyUnavailable' }, { status:409 }) }
}

import { noteLogUser, withRequestLog } from '@/lib/request-log'
import { defaultAgentCopy as agentCopy } from '@/lib/agent-copy'
import { auth } from '@/lib/api-auth'
import { agentImageQuery } from '@/lib/agent-images'
import { findCachedAgentImage } from '@/lib/agent-images-server'

async function handleGET(request: Request) {
  const headers = { 'Cache-Control': 'private, no-store' }
  if (request.headers.get('sec-fetch-site') === 'cross-site') return Response.json({ error: agentCopy.crosssiteRequestsAreNotAllowed }, { status: 403, headers })
  const session = await auth.api.getSession({ headers: request.headers })
  noteLogUser(session?.user?.id)
  if (!session?.user) return Response.json({ error: agentCopy.pleaseSignInFirst }, { status: 401, headers })
  const query = agentImageQuery.safeParse(new URL(request.url).searchParams.get('q'))
  if (!query.success) return Response.json({ error: agentCopy.imageKeywordsMustBe2160CharactersAnd }, { status: 400, headers })
  try {
    return Response.json({ image: await findCachedAgentImage(query.data, request.signal) }, { headers })
  } catch {
    return Response.json({ error: agentCopy.imageSourcesAreTemporarilyUnavailableTheResponse }, { status: 502, headers })
  }
}

export const GET = withRequestLog('/api/agent/images', handleGET)

import { defaultAgentCopy as agentCopy } from '@/lib/agent-copy'
import { auth } from '@/lib/api-auth'
import { db } from '@/lib/db'
import { activeAgentsResponse, listActiveAgents } from '@/lib/active-agents'

/** The agents (and Coordinator) working for the signed-in person right now. */
export async function GET(request: Request) {
  const session = await auth.api.getSession({ headers: request.headers })
  return activeAgentsResponse(request, session?.user?.id ?? null, userId => listActiveAgents(db, userId, undefined, session?.tokenWorkspaceId), {
    pleaseSignIn: agentCopy.pleaseSignInFirst,
    unavailable: agentCopy.unableToLoadChatHistoryPleaseTry,
    noParameters: agentCopy.activeAgentsNoParameters,
  })
}

import { noteLogUser, withRequestLog } from '@/lib/request-log'
import { defaultAgentCopy as agentCopy } from '@/lib/agent-copy'
import { z } from 'zod'
import { auth } from '@/lib/api-auth'
import { AgentStoreError, getAgentHistory } from '@/lib/agent-store'

async function handleGET(request: Request) {
  const headers = { 'Cache-Control': 'private, no-store' }
  const session = await auth.api.getSession({ headers: request.headers })
  noteLogUser(session?.user?.id)
  if (!session?.user) return Response.json({ error: agentCopy.pleaseSignInFirst }, { status: 401, headers })
  const params = new URL(request.url).searchParams
  const id = params.get('sessionId')
  if (id && !z.uuid().safeParse(id).success) return Response.json({ error: agentCopy.invalidConversationID }, { status: 400, headers })
  try {
    return Response.json(await getAgentHistory(session.user.id, id ?? undefined, params.get('new') === '1'), { headers })
  } catch (error) {
    return Response.json({ error: error instanceof AgentStoreError ? error.message : agentCopy.unableToLoadChatHistoryPleaseTry }, {
      status: error instanceof AgentStoreError ? error.status : 503, headers,
    })
  }
}

export const GET = withRequestLog('/api/agent/sessions', handleGET)

import { createPersonalWriteRoute } from '@/lib/operations/write-route'

import { personalWritesEnabled } from '@/lib/operations/write-feature'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

/** Public availability only. Never initializes auth, database or provider services. */
export function GET() {
  return Response.json({ enabled: personalWritesEnabled() }, { headers: { 'cache-control': 'no-store' } })
}

/** Separate personal browser endpoint; deliberately not a Bot/AgentKit tool.
 * Disabled requests never initialize auth, the DB pool or provider clients. */
export const POST = createPersonalWriteRoute({
  enabled: personalWritesEnabled,
  load: async () => (await import('@/lib/operations/write-runtime')).personalWriteRuntime(),
})

import { ARTIFACT_CONTENT_TYPES, artifactFileName } from '@/lib/artifacts/limits'
import { routeArtifact } from '@/lib/artifacts/route'

export const dynamic = 'force-dynamic'

/** `GET /api/artifacts/:id/versions/:n/download`: the file as it was handed over. */
export async function GET(request: Request, { params }: { params: Promise<{ artifactId: string; version: string }> }) {
  const found = await routeArtifact(request, params)
  if (found instanceof Response) return found
  const name = artifactFileName(found.title, found.kind, found.version)
  return new Response(found.content, {
    headers: {
      'content-type': ARTIFACT_CONTENT_TYPES[found.kind],
      'content-disposition': `attachment; filename="${name.replace(/[^\x20-\x7e]/g, '_').replace(/"/g, '')}"; filename*=UTF-8''${encodeURIComponent(name)}`,
      'x-content-type-options': 'nosniff',
      'cache-control': 'private, no-store',
      // A downloaded page must not run here if a browser renders it anyway.
      'content-security-policy': "sandbox; default-src 'none'",
    },
  })
}

import { frameDocument, frameHeaders } from '@mikka/protocol/artifact-frame'
import { routeArtifact } from '@/lib/artifacts/route'

export const dynamic = 'force-dynamic'

/**
 * `GET /api/artifacts/:id/versions/:n/frame`: an HTML artifact as the page the
 * viewer's sandboxed iframe loads (and 在浏览器打开 opens). Its own CSP
 * sandbox keeps it in an opaque origin either way.
 */
export async function GET(request: Request, { params }: { params: Promise<{ artifactId: string; version: string }> }) {
  const found = await routeArtifact(request, params)
  if (found instanceof Response) return found
  if (found.kind !== 'html') return new Response('Not found', { status: 404 })
  return new Response(frameDocument(found.content), { headers: frameHeaders() })
}

import { frameDocument, frameHeaders } from '@mikka/protocol/artifact-frame'
import { sharedArtifact } from '@/lib/artifacts/store'

export const dynamic = 'force-dynamic'

/** `GET /api/artifacts/shared/:token/frame`: a shared HTML artifact for the share page's sandboxed iframe. */
export async function GET(_request: Request, { params }: { params: Promise<{ token: string }> }) {
  const found = await sharedArtifact((await params).token)
  if (!found || found.kind !== 'html') return new Response('Not found', { status: 404 })
  return new Response(frameDocument(found.content), { headers: frameHeaders() })
}

import { sharedArtifact } from '@/lib/artifacts/store'
import { withRequestLog } from '@/lib/request-log'

export const dynamic = 'force-dynamic'
const privateHeaders = { 'Cache-Control': 'private, no-store', 'Referrer-Policy': 'no-referrer', 'X-Content-Type-Options': 'nosniff' }

/** The public share token is the permission, exactly as on /a/<token>.
 * Only the existing ArtifactShared props leave this endpoint. */
export const GET = withRequestLog('/api/artifacts/shared/[token]', async (_request: Request, { params }: { params: Promise<{ token: string }> }) => {
  const { token } = await params
  const found = /^mks_[A-Za-z0-9_-]{1,124}$/.test(token) ? await sharedArtifact(token) : null
  if (!found) return Response.json({ error: 'not_found' }, { status: 404, headers: privateHeaders })
  const artifact = {
    id: found.id, kind: found.kind, title: found.title, latestVersion: found.latestVersion,
    runId: found.runId, issueId: found.issueId,
    versions: found.versions.map(version => ({
      version: version.version, authorName: version.authorName, authorColor: version.authorColor,
      authorShape: version.authorShape, authorHarness: version.authorHarness, createdAt: version.createdAt,
    })),
  }
  return Response.json({ artifact, markdown: found.kind === 'markdown' ? found.content : null }, { headers: privateHeaders })
})

import { withRequestLog } from '@/lib/request-log'
import { auth, authBaseURL } from '@/lib/auth'
import { BASE_PATH } from '@/lib/base-path'
import { verificationNavigationResponse } from '@/lib/auth-verification-response'
import { toNextJsHandler } from 'better-auth/next-js'
import { handleGitHubConnectCallback } from '@/lib/github/connect-callback'

const handler = toNextJsHandler(auth)

// Next hands route handlers the URL without its base path, but better-auth
// matches routes against its full base URL (/mikka/api/auth), so put it back.
function withBasePathURL(route: (request: Request) => Promise<Response>) {
  return (request: Request) => {
    const url = new URL(request.url)
    if (url.pathname.startsWith(`${BASE_PATH}/`)) return route(request)
    url.pathname = `${BASE_PATH}${url.pathname}`
    return route(new Request(url, { method: request.method, headers: request.headers, body: request.body, duplex: 'half' } as RequestInit))
  }
}

export const GET = withRequestLog('/api/auth/[...all]', withBasePathURL(async request => await handleGitHubConnectCallback(request) ?? verificationNavigationResponse(
  request, await handler.GET(request), authBaseURL ?? 'http://localhost:3000',
)))
export const POST = withRequestLog('/api/auth/[...all]', withBasePathURL(handler.POST))

import { readAvatar } from '@/lib/account/avatar'

export const dynamic = 'force-dynamic'

/**
 * `GET /api/avatars/:userId/:sha256`: an uploaded profile picture. Avatars show
 * wherever the person does (teammates, the iOS app), like provider pictures,
 * so this needs no session. The URL names the exact bytes, so it never
 * changes; a replaced picture is a 404. Browsers keep it for a day only, so a
 * removed picture or deleted account does not linger in caches for long.
 */
export async function GET(_request: Request, { params }: { params: Promise<{ userId: string; hash: string }> }) {
  const { userId, hash } = await params
  if (!/^[A-Za-z0-9_-]{1,128}$/.test(userId) || !/^[a-f0-9]{64}$/.test(hash)) return new Response('Not found', { status: 404 })
  const found = await readAvatar(userId, hash)
  if (!found) return new Response('Not found', { status: 404, headers: { 'cache-control': 'no-store' } })
  return new Response(new Uint8Array(found.bytes), {
    headers: {
      'content-type': found.contentType,
      'content-length': String(found.bytes.length),
      'cache-control': 'public, max-age=86400',
      'x-content-type-options': 'nosniff',
      'content-security-policy': "default-src 'none'; sandbox",
    },
  })
}

import { NextResponse } from 'next/server'
import { z, ZodError } from 'zod'
import { applyStripeEvent } from '@/lib/billing/service'
import { stripeConfig, verifyStripeSignature } from '@/lib/billing/stripe'

export const runtime = 'nodejs'

/** Stripe webhook: subscription state, purchased points and refunds. Signature-checked. */
export async function POST(request: Request) {
  const secret = stripeConfig()?.webhookSecret
  if (!secret) return new NextResponse(null, { status: 404 })
  const body = await request.text()
  if (!verifyStripeSignature(body, request.headers.get('stripe-signature'), secret)) return new NextResponse(null, { status: 400 })
  try {
    const event = JSON.parse(body)
    if (event.type === 'setup_intent.succeeded') {
      await (await import('@/lib/abuse/card')).applyCardSetup(z.object({data:z.object({object:z.record(z.string(),z.unknown())})}).parse(event).data.object)
    } else if (event.type === 'checkout.session.completed' && event.data?.object?.mode === 'setup') {
      await (await import('@/lib/abuse/card')).applyCardCheckout(z.object({data:z.object({object:z.record(z.string(),z.unknown())})}).parse(event).data.object)
    } else await applyStripeEvent(event)
  } catch (error) {
    // A malformed event is refused for good; anything else (the database) is a 500 so Stripe retries.
    if (!(error instanceof ZodError || error instanceof SyntaxError)) throw error
    console.error('[billing] webhook event rejected', { name: error.name })
    return new NextResponse(null, { status: 400 })
  }
  return NextResponse.json({ received: true })
}

import { computerRoute } from '@/lib/computer/route'
export const maxDuration = 300
export async function POST(request: Request, context: { params: Promise<{ botId: string }> }) {
  return computerRoute(request, (await context.params).botId, 'handback')
}

import { computerRoute } from '@/lib/computer/route'
export const maxDuration = 300
export async function GET(request: Request, context: { params: Promise<{ botId: string }> }) {
  return computerRoute(request, (await context.params).botId)
}

import { AgentProfileError } from '@/lib/factory/agent-profile-definition'
import { agentProfileReferenceSchema } from '@/lib/factory/agent-profile-reference'
import { AgentProfileAdmissionError } from '@/lib/factory/profile-admission'
import { cloudComputerRunsEnabled } from '@/lib/cloud-computer-flag'
import { z } from 'zod'
import { auth } from '@/lib/api-auth'
import { pool } from '@/lib/db'
import { issueForUser } from '@/lib/issue-access'
import { tiptapToText } from '@/lib/tiptap-text'
import { loadWorkspaceContext } from '@/lib/workspace-access'
import { FactoryError } from '@/lib/factory/contract'
import { ComputerError } from '@/lib/computer/store'
import { latestThreadRunModel } from '@/lib/computer/run-model'
import { queueFactoryCloudRun } from '@/lib/factory/queue-cloud'

const inputSchema = z.object({ issueId: z.uuid(), harness: z.enum(['codex', 'claude_code']).optional(), profileId: agentProfileReferenceSchema.optional(), note: z.string().trim().max(10_000).optional(), needsSpec: z.boolean().optional() }).strict()
const headers = { 'Cache-Control': 'private, no-store' }

export async function POST(request: Request, { params }: { params: Promise<{ botId: string }> }) {
  if (!cloudComputerRunsEnabled()) return Response.json({ error: 'Cloud computer task unavailable' }, { status: 503, headers })
  const session = await auth.api.getSession({ headers: request.headers })
  if (!session?.user) return Response.json({ error: 'Sign in required' }, { status: 401, headers })
  if (request.headers.get('origin') !== new URL(request.url).origin) return Response.json({ error: 'Invalid origin' }, { status: 403, headers })
  const botId = (await params).botId
  const raw = await request.text()
  if (raw.length > 12_000 || !z.uuid().safeParse(botId).success) return Response.json({ error: 'Invalid request' }, { status: 400, headers })
  const parsed = inputSchema.safeParse((() => { try { return JSON.parse(raw) } catch { return null } })())
  if (!parsed.success) return Response.json({ error: 'Invalid request' }, { status: 400, headers })
  try {
    const [issue, context] = await Promise.all([issueForUser(session.user, parsed.data.issueId), loadWorkspaceContext(undefined, session.user)])
    if (!issue) return Response.json({ error: 'Task unavailable' }, { status: 404, headers })
    // One task, one thread (lib/thread-dispatch.ts): a task with a thread gets this as that thread's work.
    const { dispatchToTask, latestTaskRun } = await import('@/lib/thread-dispatch')
    const previousThread = await latestTaskRun(pool, session.user.id, parsed.data.issueId)
    const sourceEventId = previousThread && parsed.data.note ? await (await import('@/lib/factory/request-epoch')).recordOwnerFactoryContinuation(pool, session.user.id, previousThread.id, parsed.data.note) : undefined
    const result = await dispatchToTask(session.user.id, parsed.data.issueId, {
      note: parsed.data.note, sourceEventId,
      // A new thread takes 优先使用的模型's first cloud entry for this harness; the thread's next run keeps its own model.
      start: async (previous, note) => {
        const scope = { ownerId: session.user.id, workspaceId: context.workspace.id, botId }
        const needsSpec = !previous && await (await import('@/lib/factory/task-dispatch')).factoryTaskNeedsSpec(pool, session.user.id, { issueId: issue.id, botId, needsSpec: parsed.data.needsSpec })
        let runModel: import('@/lib/computer/run-model').RunModel
        let harness: 'claude_code' | 'codex'
        if (previous) {
          if (!previous.cloud || previous.cloud.botId !== botId || (previous.harness !== 'claude_code' && previous.harness !== 'codex')) throw new ComputerError(409, 'threadModelUnavailable')
          const kept = await latestThreadRunModel(pool, session.user.id, parsed.data.issueId, previous.agentId)
          if (!kept || (parsed.data.harness && parsed.data.harness !== previous.harness) ||
            (parsed.data.profileId && parsed.data.profileId !== kept.agentProfile?.profileId)) throw new ComputerError(409, 'threadProfileMismatch')
          runModel = kept
          harness = previous.harness
        } else {
          const { resolveAgentProfileDispatch } = await import('@/lib/factory/agent-profile')
          const picked = await resolveAgentProfileDispatch(pool, scope, { issueId: issue.id, stage: needsSpec ? 'spec' : 'execute', note,
            profileId: parsed.data.profileId, location: 'cloud', cloudPurpose: 'desktop',
            ...(parsed.data.harness ? { asked: { harness: parsed.data.harness } } : {}) })
          const target = picked.target
          if (target.kind !== 'cloud') throw new ComputerError(409, 'agentProfileUnavailable')
          harness = target.harness
          const ready = await (await import('@/lib/computer/auto-runtime')).ensureBotCloudRuntime(pool, { userId: session.user.id, workspaceId: context.workspace.id }, botId, { harness })
          if (!ready) throw new ComputerError(409, 'Bot computer task is unavailable')
          const source = target.entry.source
          runModel = { model: target.model, agentProfile: picked.agentProfile,
            modelDispatch: { mode: picked.selectionMode ?? (parsed.data.harness ? 'picked' : 'preference'), location: 'cloud', entry: target.entry, ...(target.routing ? { routing: target.routing } : {}) },
            ...(source.kind === 'api_key' ? { apiKeyId: source.keyId } : { subscriptionBindingId: await (await import('@/lib/model-dispatch')).bindAgentToConnection(pool, scope, ready.agentId, harness, source.connectionId, target.model) }) }
        }
        const runtime = (await pool.query('SELECT r."agentId",r."repoId",a."deviceId" FROM bot_cloud_runtimes r JOIN agents a ON a.id=r."agentId" WHERE r."botId"=$1 AND r."ownerId"=$2 AND r."workspaceId"=$3 AND r.harness=$4', [botId, session.user.id, context.workspace.id, harness])).rows[0]
        if (!runtime) throw new ComputerError(409, 'Bot computer task is unavailable')
        const actor = { userId: session.user.id, workspaceId: context.workspace.id }
        await (await import('@/lib/computer/dispatch-runtime')).prepareBotCloudTaskRuntime(pool, actor, { botId, agentId: runtime.agentId, harness, ...runModel, ...(previous?.remoteUrl ? { repo: previous.remoteUrl } : {}) })
        const deviceRepoId = previous?.remoteUrl ? (await (await import('@/lib/device-repositories')).ensureDeviceRepository(session.user.id, runtime.deviceId, previous.remoteUrl)).id : runtime.repoId
        return queueFactoryCloudRun(pool, actor, { issueId: parsed.data.issueId, note, botId, sourceEventId, needsSpec, agentId: runtime.agentId, deviceRepoId, ...(previous?.botId === null ? {withoutBot:true} : {}), title: issue.title, body: tiptapToText(issue.content), ...(previous?.readOnly ? { readOnly: true } : {}), ...(previous ? { idempotencyKey: `thread:${previous.id}:${sourceEventId ?? crypto.randomUUID()}` } : {}), ...runModel, ...(previous ? { threadRunId: previous.id } : {}) })
      },
    })
    if ('runId' in result && result.thread !== 'message') await (await import('@/lib/run-leases')).startThreadMachine({ userId: session.user.id, workspaceId: context.workspace.id }, result.runId)
    return Response.json(result, { status: 202, headers })
  } catch (error) {
    if (error instanceof AgentProfileError) return Response.json({ error: error.code }, { status: error.status, headers })
    if (error instanceof AgentProfileAdmissionError) return Response.json({ error: error.message }, { status: 409, headers })
    if (error instanceof FactoryError) return Response.json({ error: error.code }, { status: 409, headers })
    if (error instanceof ComputerError) return Response.json({ error: error.message }, { status: error.status, headers })
    return Response.json({ error: 'Cloud computer task unavailable' }, { status: 503, headers })
  }
}

import { cloudComputerTasksEnabled } from '@/lib/cloud-computer-flag'
