import { NextResponse } from 'next/server'
import { auth } from '@/lib/api-auth'
import { actAs } from '@/lib/acting-user'
import { ActionFailureError } from '@/lib/action-error'
import { db } from '@/lib/db'
import { parseSearchParams, searchIssues, SearchInputError } from '@/lib/issue-search'
import { loadWorkspaceContext, WorkspaceError } from '@/lib/workspace-access'

/**
 * GET /api/issues/search — relation picker search (MIK-16). See lib/issue-search.ts for the
 * full contract. Query params:
 *   q                    '' = recent; ORV-123 / MIK-123 / 123 = exact number; else title match.
 *                        One non-CJK character is a 400; one CJK character searches.
 *   issueId              the issue being edited; drives existingRelation and canRelate.
 *   relationKind         optional; preferred kind when reporting existingRelation.
 *   excludeId            hidden from results (usually = issueId).
 *   excludeDescendants   also hide excludeId's descendants (recursive, 20-level cap).
 *   excludeAncestors     also hide excludeId's ancestors (recursive, 20-level cap).
 *   workspaceId          defaults to the current workspace.
 *   limit (1–50, default 20), cursor (opaque, from nextCursor).
 * Response: { items, nextCursor, truncated }. truncated = the ancestor/descendant walk hit the
 * 20-level cap, so some deeper relatives may not be excluded; nextCursor = more rows exist.
 */
export async function GET(request: Request) {
  const session = await auth.api.getSession({ headers: request.headers })
  if (!session?.user) return NextResponse.json({ error: 'authRequired' }, { status: 401, headers: { 'Cache-Control': 'private, no-store' } })
  const userId = session.user.id
  try {
    const params = parseSearchParams(new URL(request.url).searchParams)
    const context = await loadWorkspaceContext(params.workspaceId ?? undefined, session.user)
    // Inside actAs, a workspace token's scope reaches the task visibility check.
    const result = await actAs(session.user, () => searchIssues(db, { userId, params, workspaceId: context.workspace.id }))
    return NextResponse.json(result, { headers: { 'Cache-Control': 'private, no-store' } })
  } catch (error) {
    if (error instanceof SearchInputError) return NextResponse.json({ error: error.code }, { status: 400 })
    if (error instanceof WorkspaceError) return NextResponse.json({ error: error.code }, { status: 403 })
    if (error instanceof ActionFailureError) return NextResponse.json({ error: error.code }, { status: error.code === 'authRequired' ? 401 : 404 })
    if (error instanceof Error && error.name === 'ZodError') return NextResponse.json({ error: 'searchInvalidParam' }, { status: 400 })
    console.error('Issue search failed', error instanceof Error ? error.name : 'UnknownError')
    return NextResponse.json({ error: 'issueSearchFailed' }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { auth } from '@/lib/api-auth'
import { activeTaskWorkspaces } from '@/lib/task-workspace'
import { withRequestLog } from '@/lib/request-log'
import { LIVE_ID } from '@/lib/live/events'
import { liveGatewayConfig } from '@/lib/live/scope'
import { workspaceLiveTicket } from '@/lib/enterprise/live-authority'
import { desktopBearerHeaders } from '@/lib/desktop-rpc/handler'
import { homeScopeProof } from '@/lib/live/home-scope-proof'

export const dynamic = 'force-dynamic'
const headers = { 'cache-control': 'private, no-store' }

async function ticket(request: Request) {
  // A native session grants the same owner channel as its browser session. PATs
  // remain workspace-scoped and never grant this ambient owner capability.
  const bearerHeaders = request.headers.has('authorization') ? desktopBearerHeaders(request) : null
  if (request.headers.has('authorization') && !bearerHeaders) return NextResponse.json({ error: 'authRequired' }, { status: 401, headers })
  // A new capability must not extend a revoked session through its cached cookie.
  const session = await auth.api.getSession({ headers: bearerHeaders ?? request.headers, query: { disableCookieCache: true } })
  if (!session?.user) return NextResponse.json({ error: 'authRequired' }, { status: 401, headers })
  const workspaceId = (new URL(request.url).searchParams.get('workspace') ?? '').toLowerCase()
  if (!LIVE_ID.test(workspaceId)) return NextResponse.json({ error: 'workspaceAccessDenied' }, { status: 403, headers })
  const [workspace] = await activeTaskWorkspaces(session.user, workspaceId)
  if (!workspace) return NextResponse.json({ error: 'workspaceAccessDenied' }, { status: 403, headers })
  const config = liveGatewayConfig(process.env)
  if (!config) return NextResponse.json({ url: null, protocol: null, expiresAt: null }, { headers })
  const scope = { ownerId: session.user.id, workspaceId }
  const result = await workspaceLiveTicket(scope, session.session?.id ?? '', config)
  if (result.status === 'denied') return NextResponse.json({ error: 'workspaceAccessDenied' }, { status: 403, headers })
  if (result.status === 'pending') return NextResponse.json({ url: null, protocol: null, expiresAt: null }, { headers })
  const issued = result.ticket
  const homeScope = workspace.kind === 'personal' ? homeScopeProof(scope, issued.expiresAt, config.secret) : null
  return NextResponse.json({ ...issued, ...(homeScope ? { homeScope } : {}) }, { headers })
}

