import { and, eq, inArray, sql } from 'drizzle-orm'
import { listOwnerBots } from '@/lib/coordinator/coordinator-bot'
import { withRequestLog, noteLogUser } from '@/lib/request-log'
import { db } from '@/lib/db'
import { agentRuns } from '@/lib/db/schema'
import { botChats } from '@/lib/coordinator/store'
import { chatPreview } from '@/lib/agent-history'
import { chatPreferences } from '@/lib/chat-preferences'
import { listSuggestions } from '@/lib/suggestions/store'
import { loadWorkspaceContext } from '@/lib/workspace-access'
import { json, mobileUser, unauthorized } from '@/lib/mobile-api'
import { ownerListRead } from '@/lib/live/list-read-server'

export const dynamic = 'force-dynamic'

/** A chat's latest message as the one plain line the 对话 list shows; never OpenUI source. */
const homeLine = (text: string | null | undefined) => text ? chatPreview(text) ?? '' : null

const RUNNING = ['queued', 'preparing', 'running', 'finishing'] as const

/**
 * `GET /api/mobile/home`: what the app's home list and drawer show: the person, their
 * workspace, their bots with each chat's latest line as plain text (an empty
 * string for a card with no words; the Coordinator first, marked `coordinator`), and the counts beside
 * 建议 and 线程 (docs/design/mobile.md, "Where it lives"). `live.workspaceId` is the
 * person's own home channel (lib/live/owner-scope.ts) the app listens on for its
 * owner-wide keys; null when there is none (the app then reads once a minute).
 */
async function handleGET(request: Request) {
  const user = await mobileUser(request)
  noteLogUser(user?.id)
  if (!user) return unauthorized()
  const context = await loadWorkspaceContext(undefined, user)
  const recent = and(eq(agentRuns.userId, user.id), eq(agentRuns.workspaceId, context.workspace.id),
    sql`${agentRuns.createdAt} > now() - interval '30 days'`)
  const [botRows, chats, suggestions, perBot, preferences, live] = await Promise.all([
    // The Coordinator first, marked `coordinator` (lib/coordinator/coordinator-bot.ts listOwnerBots).
    listOwnerBots(user.id, context.workspace.id),
    botChats(user.id),
    listSuggestions(user.id),
    // One read for 线程's counts and each bot's waiting mark: the counts per bot, summed here for the drawer.
    db.select({
      botId: agentRuns.botId,
      running: sql<number>`count(*) filter (where ${inArray(agentRuns.status, [...RUNNING])})`,
      waiting: sql<number>`count(*) filter (where ${eq(agentRuns.status, 'waiting_input')})`,
    }).from(agentRuns).where(recent).groupBy(agentRuns.botId),
    chatPreferences(user.id),
    ownerListRead(user.id),
  ])
  // Each bot's threads waiting on the person: the home row's waiting mark outranks its unread count.
  const waiting = new Map(perBot.map(row => [row.botId, Number(row.waiting)]))
  const counts = perBot.reduce((sum, row) => ({ running: sum.running + Number(row.running), waiting: sum.waiting + Number(row.waiting) }), { running: 0, waiting: 0 })
  const own = (key: string) => {
    const preference = preferences[key]
    return { hidden: preference?.hidden ?? false, markedUnread: preference?.markedUnread ?? false, pinOrder: preference?.pinOrder ?? null, listOrder: preference?.listOrder ?? null }
  }
  const botIds = new Set(botRows.map(bot => bot.id))
  return json({
    user: { id: user.id, name: user.name, email: user.email, image: user.image ?? null },
    workspace: context.workspace,
    workspaces: context.choices,
    bots: botRows.map(bot => ({ ...bot, line: homeLine(chats[bot.id]?.line), at: chats[bot.id]?.at ?? null, working: chats[bot.id]?.working ?? false,
      pinned: preferences[bot.id]?.pinned ?? bot.coordinator, waiting: waiting.get(bot.id) ?? 0, ...own(bot.id) })),
    // The person's own state for each group chat they changed on the home list, by conversation id.
    groupPreferences: Object.fromEntries(Object.entries(preferences).filter(([key]) => !botIds.has(key) && /^[0-9a-f-]{36}$/i.test(key))
      .map(([key, preference]) => [key, { pinned: preference.pinned, ...own(key) }])),
    threads: counts,
    suggestions: suggestions.length,
    live: { ownerId: live.ownerId, workspaceId: live.workspaceId },
  })
}

export const GET = withRequestLog('/api/mobile/home', handleGET)

import { z } from 'zod'
import { withRequestLog, noteLogUser } from '@/lib/request-log'
import { forbiddenOrigin, json, mobileUser, unauthorized, writeAllowed } from '@/lib/mobile-api'
import { ActionFailureError } from '@/lib/action-error'
import { pool } from '@/lib/db'
import { ExecutionSettings } from '@/lib/execution-settings'
import { botModelMenu, botModelScope, chooseBotModel, refreshBotModelMenu } from '@/lib/bot-model-menu'
import { tokenWorkspace } from '@/lib/tokens/principal'
import { openChatBotId } from '@/lib/coordinator/coordinator-bot'

export const dynamic = 'force-dynamic'

const botParam = z.uuid().nullable()
// An option id as the menu lists it: a binding uuid, Mikka 默认, or `apikey:<keyId>:<model>` (lib/bot-model-menu-view.ts).
const choice = z.strictObject({ bot: botParam, id: z.string().min(1).max(300) })
const temporaryChoice = z.strictObject({ bot: z.uuid(), id: z.uuid(), mode: z.literal('temporary-if-absent') })
const restoreChoice = z.strictObject({ bot: z.uuid(), mode: z.literal('restore-implicit'), bindingId: z.uuid(), revision: z.string().regex(/^[0-9]{1,10}$/) })
const putChoice = z.union([choice, temporaryChoice, restoreChoice])

function failed(error: unknown) {
  if (error instanceof ActionFailureError && (error.code === 'botNotFound' || error.code === 'workspaceAccessDenied')) return json({ error: 'botNotFound' }, 404)
  if (error instanceof ActionFailureError && error.code === 'executionModelUnknown') return json({ error: 'modelUnavailable' }, 409)
  throw error
}

/** `GET /api/mobile/model?bot=<id>`: the composer's model menu for a bot, or the Coordinator (no `bot`). */
async function handleGET(request: Request) {
  const user = await mobileUser(request)
  noteLogUser(user?.id)
  if (!user) return unauthorized()
  const bot = botParam.safeParse(new URL(request.url).searchParams.get('bot'))
  if (!bot.success) return json({ error: 'invalidBot' }, 400)
  try {
    const botId = await openChatBotId(user, bot.data)
    const scope = await botModelScope(user.id, botId, user[tokenWorkspace])
    if (new URL(request.url).searchParams.get('choiceState') === '1')
      return json(await botModelMenu(pool, new ExecutionSettings(pool), scope, botId, Date.now(), true))
    return json(await botModelMenu(pool, new ExecutionSettings(pool), scope, botId))
  } catch (error) { return failed(error) }
}

/**
 * `PUT /api/mobile/model` with `{ bot, id }`: saves the pick for the bot's next
 * runs and returns the menu. 409 `modelUnavailable` when the credential is not
 * usable here any more.
 */
async function handlePUT(request: Request) {
  const user = await mobileUser(request)
  noteLogUser(user?.id)
  if (!user) return unauthorized()
  if (!writeAllowed(request)) return forbiddenOrigin()
  const body = putChoice.safeParse(await request.json().catch(() => null))
  if (!body.success) return json({ error: 'invalidModel' }, 400)
  try {
    const botId = await openChatBotId(user, body.data.bot)
    const scope = await botModelScope(user.id, botId, user[tokenWorkspace])
    if ('mode' in body.data) {
      if (!botId) return json({ error: 'invalidBot' }, 400)
      const settings = new ExecutionSettings(pool)
      if (body.data.mode === 'restore-implicit') {
        const restored = await settings.restoreTemporaryBotModel(scope, botId, body.data)
        return restored ? json({ restored: true, preferenceState: 'absent' }) : json({ error: 'modelChanged' }, 409)
      }
      const temporarySelection = await settings.setTemporaryBotModel(scope, botId, body.data.id)
      if (!temporarySelection) return json({ error: 'modelChanged' }, 409)
      return json({ ...await botModelMenu(pool, settings, scope, botId), temporarySelection })
    }
    return json(await chooseBotModel(pool, new ExecutionSettings(pool), scope, botId, body.data.id))
  } catch (error) { return failed(error) }
}

/** `POST /api/mobile/model` with `{ bot }`: 刷新, re-reads the menu after asking each subscription for its models. */
async function handlePOST(request: Request) {
  const user = await mobileUser(request)
  noteLogUser(user?.id)
  if (!user) return unauthorized()
  if (!writeAllowed(request)) return forbiddenOrigin()
  const body = z.strictObject({ bot: botParam }).safeParse(await request.json().catch(() => null))
  if (!body.success) return json({ error: 'invalidBot' }, 400)
  try {
    const botId = await openChatBotId(user, body.data.bot)
    const scope = await botModelScope(user.id, botId, user[tokenWorkspace])
    return json(await refreshBotModelMenu(pool, new ExecutionSettings(pool), scope, botId))
  } catch (error) { return failed(error) }
}

export const GET = withRequestLog('/api/mobile/model', handleGET)
export const PUT = withRequestLog('/api/mobile/model', handlePUT)
export const POST = withRequestLog('/api/mobile/model', handlePOST)

import { randomBytes, timingSafeEqual } from 'node:crypto'
import { NextResponse } from 'next/server'
import { withRequestLog } from '@/lib/request-log'
import { auth } from '@/lib/auth'
import { withBasePath } from '@/lib/base-path'
import { mobileWebTarget } from '@/lib/mobile-web-target'
import { handoffSessionCookie, openHandoff, sealHandoff } from '@/lib/mobile-handoff'
import { mobileWebWorkspace, MobileWebScopeError } from '@/lib/mobile-web-scope'
import en from '@/messages/en.json'
import zh from '@/messages/zh-CN.json'

export const dynamic = 'force-dynamic'
const pendingCookie = 'mikka-mobile-handoff'
const path = withBasePath('/api/mobile/open')
const safeHeaders = { 'Cache-Control': 'private, no-store', 'Referrer-Policy': 'no-referrer', 'Content-Security-Policy': "default-src 'none'; form-action 'self'; frame-ancestors 'none'; base-uri 'none'", 'X-Content-Type-Options': 'nosniff' }
const escape = (value: string) => value.replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]!)
const same = (a: string, b: string) => Buffer.byteLength(a) === Buffer.byteLength(b) && timingSafeEqual(Buffer.from(a), Buffer.from(b))
const cookieOptions = (request: Request) => ({ httpOnly: true, secure: new URL(request.url).protocol === 'https:', sameSite: 'strict' as const, path, maxAge: 60 })

/** Consume the native token, but never sign in merely by following a link. */
async function handleGET(request: Request) {
  const url = new URL(request.url)
  const target = mobileWebTarget(url.searchParams.get('to'))
  const token = url.searchParams.get('token')
  if (!token) return NextResponse.redirect(new URL(withBasePath(target), url.origin), { status: 303, headers: safeHeaders })
  try {
    // HTTP router mode prevents nextCookies() from mutating the ambient Next
    // response before the person confirms. Direct auth.api calls run that hook.
    const exchanged = await auth.handler(new Request(new URL(withBasePath('/api/auth/one-time-token/verify'), url.origin), {
      method: 'POST', headers: { 'content-type': 'application/json', origin: url.origin }, body: JSON.stringify({ token }),
    }))
    if (!exchanged.ok) throw new Error('Mobile handoff token unavailable')
    const session = await exchanged.json() as { user: { id: string; email: string } }
    const workspaceId = await mobileWebWorkspace(session.user.id, target)
    const headers = exchanged.headers
    const csrf = randomBytes(32).toString('base64url')
    const state = sealHandoff({ cookies: headers.getSetCookie(), target, workspaceId, origin: url.origin, csrf, expires: Date.now() + 60_000 }, (await auth.$context).secret)
    if (state.length > 3500) throw new Error('Mobile handoff cookie exceeds browser limit')
    const copy = (request.headers.get('accept-language')?.startsWith('zh') ? zh : en).MobileHandoff
    const html = `<!doctype html><html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escape(copy.title)}</title><main><h1>${escape(copy.title)}</h1><p>${escape(session.user.email)}</p><form method="post" action="${escape(path)}"><input type="hidden" name="csrf" value="${csrf}"><button type="submit">${escape(copy.confirm)}</button></form><a href="${escape(withBasePath(target))}">${escape(copy.cancel)}</a></main></html>`
    const result = new NextResponse(html, { headers: { ...safeHeaders, 'Content-Type': 'text/html; charset=utf-8' } })
    result.cookies.set(pendingCookie, state, cookieOptions(request))
    return result
  } catch (error) {
    if (error instanceof MobileWebScopeError) return new NextResponse(null, { status: 403, headers: safeHeaders })
    return NextResponse.redirect(new URL(withBasePath(target), url.origin), { status: 303, headers: safeHeaders })
  }
}

/** Same-origin, browser-bound confirmation; recheck session revocation before copying cookies. */
async function handlePOST(request: Request) {
  const url = new URL(request.url)
  if (request.headers.get('origin') !== url.origin) return new NextResponse(null, { status: 403, headers: safeHeaders })
  const cookie = request.headers.get('cookie')?.split(';').map(value => value.trim()).find(value => value.startsWith(`${pendingCookie}=`))?.slice(pendingCookie.length + 1)
  const state = cookie ? openHandoff(cookie, (await auth.$context).secret) : null
  const form = await request.formData().catch(() => null)
  const csrf = form?.get('csrf')
  if (!state || state.origin !== url.origin || typeof csrf !== 'string' || !same(state.csrf, csrf)) return new NextResponse(null, { status: 403, headers: safeHeaders })
  const session = await auth.api.getSession({ headers: new Headers({ cookie: handoffSessionCookie(state.cookies) }), query: { disableCookieCache: true } })
  if (!session) return new NextResponse(null, { status: 403, headers: safeHeaders })
  let workspaceId: string | null
  try { workspaceId = await mobileWebWorkspace(session.user.id, state.target) }
  catch { return new NextResponse(null, { status: 403, headers: safeHeaders }) }
  if (workspaceId !== (state.workspaceId ?? null)) return new NextResponse(null, { status: 403, headers: safeHeaders })
  const response = NextResponse.redirect(new URL(withBasePath(mobileWebTarget(state.target)), url.origin), { status: 303, headers: safeHeaders })
  // Expire only this ephemeral credential, preserving session revocation semantics.
  response.cookies.set(pendingCookie, '', { ...cookieOptions(request), maxAge: 0 })
  if (workspaceId) response.cookies.set('mikka-workspace', workspaceId, { httpOnly: true, sameSite: 'lax', secure: url.protocol === 'https:', path: '/', maxAge: 31536000 })
  for (const value of state.cookies) response.headers.append('set-cookie', value)
  return response
}
export const GET = withRequestLog('/api/mobile/open', handleGET)
export const POST = withRequestLog('/api/mobile/open', handlePOST)

import { z } from 'zod'
import { withRequestLog, noteLogUser } from '@/lib/request-log'
import { ActionFailureError } from '@/lib/action-error'
import { forbiddenOrigin, json, mobileUser, unauthorized, writeAllowed } from '@/lib/mobile-api'
import { decidePendingAction } from '@/lib/pending-actions'
import { pendingActionsOutsideToken } from '@/lib/tokens/scope'

export const dynamic = 'force-dynamic'

type Params = { params: Promise<{ id: string }> }

/**
 * `POST /api/mobile/pending-actions/:id` with `{ approve }`: the person
 * approves (runs) or declines one proposal from the app, as the web's
 * decidePendingAction server action does. The list is `/api/pending-actions`.
 * 409 when it was already decided or has expired.
 */
async function handlePOST(request: Request, { params }: Params) {
  const user = await mobileUser(request)
  noteLogUser(user?.id)
  if (!user) return unauthorized()
  if (!writeAllowed(request)) return forbiddenOrigin()
  const id = z.uuid().safeParse((await params).id)
  const body = z.object({ approve: z.boolean() }).safeParse(await request.json().catch(() => null))
  if (!id.success || (await pendingActionsOutsideToken(user, [id.data])).size) return json({ error: 'pendingActionUnavailable' }, 409)
  if (!body.success) return json({ error: 'invalidInput' }, 400)
  try {
    const { status, error } = await decidePendingAction(user.id, id.data, body.data.approve)
    return json({ status, reason: error })
  } catch (error) {
    if (error instanceof ActionFailureError) return json({ error: error.code }, 409)
    throw error
  }
}

