export const dynamic = 'force-dynamic'

/** The first completion is immutable; retries also recover a failed enqueue. */
async function handlePOST(request: Request, { params }: { params: Promise<{ runId: string }> }) {
  const caller = await authenticateDevice(request)
  if (!caller) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  const { runId } = await params
  const parsed = runCompleteRequest.safeParse(await request.json().catch(() => null))
  if (!parsed.success) {
    // A malformed replay cannot change a completed run. Preserve the daemon's
    // idempotent acknowledgement without skipping valid publication retries.
    const [ended] = await db.select({ status: agentRuns.status }).from(agentRuns).innerJoin(devices, eq(devices.id, agentRuns.deviceId))
      .where(and(eq(agentRuns.id, runId), eq(agentRuns.userId, caller.userId), eq(devices.ownerId, caller.userId), ...(caller.scopeDeviceId ? [eq(devices.id, caller.scopeDeviceId)] : []))).limit(1)
    if (ended && !(UNFINISHED_RUN_STATUSES as readonly string[]).includes(ended.status)) return new NextResponse(null, { status: 204 })
    return NextResponse.json({ error: 'Invalid completion.' }, { status: 400 })
  }
  let result: Awaited<ReturnType<typeof persistRunCompletion>>
  // 4e2 ②: report / error text from a cloud worker is masked before it is stored.
  const failureDetails = completionFailureDetails(parsed.data, runId)
  const { failureDetails: _suppliedFailure, ...body } = parsed.data
  const completion = maskDeep({ ...body, ...(failureDetails ? { failureDetails } : {}) }, await secretMaskerFor({ workspaceId: caller.scopeWorkspaceId, ownerId: caller.userId }))
  try { result = await persistRunCompletion(caller.userId, runId, completion, caller.scopeDeviceId) }
  catch (error) {
    if (error instanceof ImprovementError) return NextResponse.json({ error: error.code }, { status: 409 })
    throw error
  }
  if (!result) return NextResponse.json({ error: 'Unknown run.' }, { status: 404 })
  stopRecordingsAfter([runId])
  if (result.publicationPending) {
    try { await startRunPublication(runId) }
    catch { return NextResponse.json({ error: 'Result publication is temporarily unavailable.' }, { status: 503, headers: { 'Retry-After': '15' } }) }
  } else {
    await dispatchCompletedIssue(result, dispatchLinearIssueSync)
    afterJob('after:coordinator-wake', () => wakeCoordinator(result.userId))
    // How it came out, for the right column (R-52); a run still publishing is judged by the minute sweep.
    afterJob('after:run-outcome-judge', () => judgeRunOutcome(runId).catch(() => null))
  }
  return new NextResponse(null, { status: 204 })
}

export const POST = withDeviceRoute(handlePOST)

import { withDeviceRoute } from '@/lib/device-route'
import { z } from 'zod'
import { pool } from '@/lib/db'
import { authenticateDevice } from '@/lib/device-link'
import { decide } from '@/lib/coordinator/decide'

type ServerDecisionAnswer = { type: 'predicate'; name: string; probability: number } | { type: 'choice'; name: string; choice: string }
export const dynamic = 'force-dynamic'
const name = z.string().regex(/^[a-zA-Z][a-zA-Z0-9_]{0,63}$/)
const instructions = z.string().min(1).max(4000)
const payload = z.object({
  purpose: z.literal('computer-action'),
  input: z.string().max(16000),
  questions: z.array(z.discriminatedUnion('type', [
    z.object({ type: z.literal('predicate'), name, instructions }).strict(),
    z.object({ type: z.literal('choice'), name, instructions, choices: z.array(z.object({ value: z.string().min(1).max(256), description: z.string().max(1000).optional() }).strict()).min(1).max(20) }).strict(),
  ])).min(1).max(20),
}).strict()

/** A daemon run asks the server's Decisions API (packages/daemon/src/server-decision.ts). */
async function handlePOST(request: Request, { params }: { params: Promise<{ runId: string }> }) {
  const caller = await authenticateDevice(request)
  if (!caller) return Response.json({ error: 'unauthorized' }, { status: 401 })
  const { runId } = await params
  const parsed = payload.safeParse(await request.json().catch(() => null))
  if (!z.uuid().safeParse(runId).success || !parsed.success) return Response.json({ error: 'invalidRequest' }, { status: 400 })
  // Same liveness as the run's tool-approval check: the caller's own unpaused, unstopped, leased run on its enabled device.
  const { rows: [run] } = await pool.query<{ botId: string | null }>(`SELECT r."botId" FROM agent_runs r JOIN devices d ON d.id=r."deviceId" AND d."ownerId"=r."userId" AND d.enabled=true
    WHERE r.id=$1 AND r."userId"=$2 AND ($3::uuid IS NULL OR r."deviceId"=$3::uuid) AND r.status=ANY($4::text[]) AND r."stopRequestedAt" IS NULL AND r."leaseExpiresAt">now()`,
  [runId, caller.userId, caller.scopeDeviceId ?? null, ['preparing', 'running', 'waiting_input']])
  if (!run) return Response.json({ error: 'decisionUnavailable' }, { status: 409 })
  const { purpose, input, questions } = parsed.data
  const { hostedBillingScope } = await import('@/lib/abuse/context')
  const { executionWorkspace } = await import('@/lib/execution-settings')
  let answers: Awaited<ReturnType<typeof decide>> = null
  try { answers = await hostedBillingScope.run({ workspaceId: await executionWorkspace(caller.userId, run.botId), ownerId: caller.userId }, () => decide(`daemon-${purpose}`, input, questions, request.signal)) } catch { answers = null }
  if (!answers) return Response.json({ answers: null })
  return Response.json({ answers: [...answers.values()].flatMap((answer): ServerDecisionAnswer[] => answer.type === 'predicate' ? [{ type: answer.type, name: answer.name, probability: answer.probability }]
    : answer.type === 'choice' ? [{ type: answer.type, name: answer.name, choice: answer.choice }] : []) })
}

export const POST = withDeviceRoute(handlePOST)

import { withDeviceRoute } from '@/lib/device-route'
import { NextResponse } from 'next/server'
import { and, eq, sql } from 'drizzle-orm'
import { runEventBatchSchema } from '@mikka/protocol/device'
import { db, pool } from '@/lib/db'
import { agentRuns, devices, runChunks } from '@/lib/db/schema'
import { authenticateDevice } from '@/lib/device-link'
import { computerEventsMatch } from '@/lib/computer/events'
import { secretMaskerFor } from '@/lib/secrets/runtime'
import { persistRunEventBatch } from '@/lib/secrets/run-events'

export const dynamic = 'force-dynamic'

/** A run the caller's token may report on: it belongs to one of their devices. */
async function ownedRun(runId: string, userId: string): Promise<boolean> {
  const [row] = await db
    .select({ id: agentRuns.id })
    .from(agentRuns)
    .innerJoin(devices, eq(devices.id, agentRuns.deviceId))
    .where(and(eq(agentRuns.id, runId), eq(devices.ownerId, userId)))
    .limit(1)
  return Boolean(row)
}

/**
 * `POST /v1/runs/:runId/events`: a batch of the run's UI message chunks.
 * `fromSeq` makes a re-sent batch land once, so a lost response costs nothing.
 */
async function handlePOST(request: Request, { params }: { params: Promise<{ runId: string }> }) {
  const caller = await authenticateDevice(request)
  if (!caller) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  const { runId } = await params
  if (!await ownedRun(runId, caller.userId)) return NextResponse.json({ error: 'Unknown run.' }, { status: 404 })
  const parsed = runEventBatchSchema.safeParse(await request.json().catch(() => null))
  if (!parsed.success) return NextResponse.json({ error: 'Invalid event batch.' }, { status: 400 })
  if (parsed.data.chunks.some(chunk => chunk.type === 'data-computer')) {
    const binding = caller.scopeDeviceId && caller.scopeWorkspaceId
      ? (await pool.query(`SELECT b."botId" FROM computer_run_bindings b JOIN agent_runs r ON r.id=b."runId" AND r."userId"=b."ownerId"
        WHERE b."runId"=$1 AND b."ownerId"=$2 AND b."workspaceId"=$3 AND r."deviceId"=$4`, [runId, caller.userId, caller.scopeWorkspaceId, caller.scopeDeviceId])).rows[0]
      : undefined
    if (!computerEventsMatch(parsed.data.chunks, runId, binding?.botId ?? null)) return NextResponse.json({ error: 'Invalid computer event.' }, { status: 400 })
  }
  // 4e2 ②: chunks from a cloud worker (workspace-scoped token) are masked before they are stored.
  // Identity when the deployment has no workspace encryption key or the workspace has no secret of 8+ characters.
  const mask = await secretMaskerFor({ workspaceId: caller.scopeWorkspaceId, ownerId: caller.userId })
  await persistRunEventBatch(runId, parsed.data.fromSeq, parsed.data.chunks, mask)
  const [tail] = await db
    .select({ seq: sql<number | null>`max(${runChunks.seq})` })
    .from(runChunks)
    .where(eq(runChunks.runId, runId))
  return NextResponse.json({ offset: String(tail?.seq ?? 0) })
}

export const POST = withDeviceRoute(handlePOST)

import { z } from 'zod'
import { withDeviceRoute } from '@/lib/device-route'
import { isDeviceAuthorityError } from '@/lib/db/device-scope'
import { authenticateDevice } from '@/lib/device-link'
import { pool } from '@/lib/db'
import { AgentToolApprovalStore } from '@/lib/agent-tool-approval/store'
import { issuePolicySnapshot, policyDistributionContext } from '@/lib/agent-tool-approval/policy-distribution'
import { requestDevicePolicyIssuer } from '@/lib/agent-tool-approval/local-cloud-issuer'
import { signedPolicySnapshotSchema } from '@mikka/protocol/policy-snapshot'
import { verifyPolicySnapshot } from '@mikka/protocol/node-policy-snapshot'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'
const headers = {'cache-control':'no-store'}
async function handle(request: Request, {params}: {params:Promise<{runId:string}>}) {
  const caller = await authenticateDevice(request)
  if (!caller) return Response.json({error:'Unauthorized'},{status:401,headers})
  const {runId} = await params
  const schema = z.strictObject({deviceId:z.uuid(),snapshot:signedPolicySnapshotSchema})
  const input = request.method === 'GET' ? z.strictObject({deviceId:z.uuid()}).safeParse({deviceId:new URL(request.url).searchParams.get('deviceId')}) : schema.safeParse(await request.json().catch(()=>null))
  if (!z.uuid().safeParse(runId).success || !input.success || (caller.scopeDeviceId && caller.scopeDeviceId !== input.data.deviceId)) return Response.json({error:'invalidRequest'},{status:400,headers})
  try {
    const snapshot = 'snapshot' in input.data ? signedPolicySnapshotSchema.parse(input.data.snapshot) : undefined
    const current = await new AgentToolApprovalStore(pool).policyDistribution({userId:caller.userId,deviceId:input.data.deviceId},runId,snapshot?.payload.revision)
    if (caller.scopeWorkspaceId && !current.workspaceIds.includes(caller.scopeWorkspaceId)) throw Error('policyScopeUnavailable')
    const context = policyDistributionContext(await requestDevicePolicyIssuer(request,caller,input.data.deviceId,runId),caller.userId,input.data.deviceId,runId,current)
    if (!snapshot) return Response.json(context,{headers})
    // Verify the original server signature and retain its exact final composed
    // policy. The current CLI revision alone cannot reconstruct Factory/computer grants.
    const prior = verifyPolicySnapshot(snapshot,context,{runId,deviceId:input.data.deviceId,revision:current.revision},{allowExpired:true})
    return Response.json(issuePolicySnapshot(context,prior.payload.policy),{headers})
  } catch (error) {
    // A revoked token is an authentication failure: withDeviceRoute answers 401, not a policy conflict.
    if (isDeviceAuthorityError(error)) throw error
    return Response.json({error:'policySnapshotUnavailable'},{status:409,headers})
  }
}
export const GET = withDeviceRoute(handle)
export const POST = withDeviceRoute(handle)

import { withDeviceRoute } from '@/lib/device-route'
import { NextResponse } from 'next/server'
import { and, eq, inArray, isNull, ne, or, sql } from 'drizzle-orm'
import { runPatchSchema } from '@mikka/protocol/device'
import { db } from '@/lib/db'
import { agentRuns, devices } from '@/lib/db/schema'
import { authenticateDevice } from '@/lib/device-link'
import { maskFor } from '@/lib/secrets/runtime'
import { runChanged } from '@/lib/live/panels'
import { runListChanged } from '@/lib/live/lists'

export const dynamic = 'force-dynamic'

/** States the daemon may report mid-run; the end comes through `/complete`. */
const LIVE_STATES = ['queued', 'preparing', 'running', 'waiting_input', 'finishing'] as const

async function ownedRun(runId: string, userId: string): Promise<boolean> {
  const [row] = await db
    .select({ id: agentRuns.id })
    .from(agentRuns)
    .innerJoin(devices, eq(devices.id, agentRuns.deviceId))
    .where(and(eq(agentRuns.id, runId), eq(devices.ownerId, userId)))
    .limit(1)
  return Boolean(row)
}

/** `PATCH /v1/runs/:runId`: the run's live state, session and worktree. */
async function handlePATCH(request: Request, { params }: { params: Promise<{ runId: string }> }) {
  const caller = await authenticateDevice(request)
  if (!caller) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  const { runId } = await params
  if (!await ownedRun(runId, caller.userId)) return NextResponse.json({ error: 'Unknown run.' }, { status: 404 })
  const parsed = runPatchSchema.safeParse(await request.json().catch(() => null))
  if (!parsed.success) return NextResponse.json({ error: 'Invalid patch.' }, { status: 400 })
  // 4e2 item 4: the error text is agent/harness output; mask it like run events.
  const patch = parsed.data.error !== undefined ? { ...parsed.data, error: await maskFor({ workspaceId: caller.scopeWorkspaceId, ownerId: caller.userId }, parsed.data.error) } : parsed.data
  if (!(LIVE_STATES as readonly string[]).includes(patch.state)) {
    // The end itself comes through `/complete`, which carries no error. A
    // failed run's reason arrives here, just before it: keep it (the first one
    // wins) without letting this patch move the run's state.
    if (patch.state === 'failed' && patch.error) {
      const changed = await db.update(agentRuns)
        .set({ error: patch.error, updatedAt: new Date() })
        .where(and(eq(agentRuns.id, runId), isNull(agentRuns.error), inArray(agentRuns.status, [...LIVE_STATES, 'paused', 'failed'])))
        .returning({ id: agentRuns.id })
      if (changed.length) { await runListChanged(db, runId); await runChanged(db, runId) }
    }
    return new NextResponse(null, { status: 204 })
  }
  const changed = await db.update(agentRuns)
    .set({
      status: sql`CASE WHEN ${agentRuns.status}='paused' THEN 'paused' ELSE ${patch.state} END`,
      resumeStatus: sql`CASE WHEN ${agentRuns.status}='paused' THEN ${patch.state} ELSE NULL END`,
      ...(patch.sessionId !== undefined ? { sessionId: patch.sessionId } : {}),
      ...(patch.worktree !== undefined ? { worktreePath: patch.worktree } : {}),
      ...(patch.error !== undefined ? { error: patch.error } : {}),
      updatedAt: new Date(),
    })
    // A run paused on its quota has ended on the daemon; a late patch does not move it.
    .where(and(eq(agentRuns.id, runId), inArray(agentRuns.status, [...LIVE_STATES, 'paused']), or(isNull(agentRuns.pauseReason), ne(agentRuns.pauseReason, 'quota_exhausted'))))
    .returning({ id: agentRuns.id })
  // Supervisor state transitions use this route. Its periodic device lease
  // heartbeat and streaming chunks have separate writers and send no list key.
  if (changed.length) { await runListChanged(db, runId); await runChanged(db, runId) }
  return new NextResponse(null, { status: 204 })
}

export const PATCH = withDeviceRoute(handlePATCH)

import { withDeviceRoute } from '@/lib/device-route'
import { screenCaptureRequest } from '@mikka/protocol/capture'
import { screenCaptures } from '@/lib/captures/screen'
import { maskFor } from '@/lib/secrets/runtime'
import { captureFailure, captureJson, deviceRun } from '@/lib/captures/device'

export const dynamic = 'force-dynamic'
// A recording's file comes off the machine on stop.
export const maxDuration = 120

/**
 * `POST /v1/runs/:runId/screen`: the cloud computer's capture tools, relayed
 * by the cloud worker for the thread it runs. Only a worker scoped to the
 * run's workspace may call it; the desktop is the one the run is bound to.
 */
async function handlePOST(request: Request, { params }: { params: Promise<{ runId: string }> }) {
  const found = await deviceRun(request, (await params).runId)
  if (found instanceof Response) return found
  if (!found.caller.scopeWorkspaceId) return captureJson({ error: 'Cloud computer worker required.' }, 403)
  const parsed = screenCaptureRequest.safeParse(await request.json().catch(() => null))
  if (!parsed.success) return captureJson({ error: 'Invalid request.' }, 400)
  const caller = { userId: found.owner.userId, workspaceId: found.caller.scopeWorkspaceId, deviceId: found.deviceId, tokenId: found.caller.tokenId }
  // 4e2 item 4: capture titles and step labels come from the agent; the pixels themselves cannot be masked.
  const input = 'title' in parsed.data && typeof parsed.data.title === 'string' ? { ...parsed.data, title: await maskFor({ workspaceId: caller.workspaceId, ownerId: caller.userId }, parsed.data.title) }
    : parsed.data.action === 'step' ? { ...parsed.data, label: await maskFor({ workspaceId: caller.workspaceId, ownerId: caller.userId }, parsed.data.label) } : parsed.data
  if (input.action === 'step')
    return captureJson({ action: input.action, recorded: await screenCaptures.step(caller, found.owner.runId, input.label, input.source) })
  if (input.action === 'screenshot') {
    const result = await screenCaptures.screenshot(caller, found.owner.runId, input.title, request.signal)
    return 'error' in result ? captureFailure(result) : captureJson({ action: input.action, capture: result })
  }
  if (input.action === 'start_recording') {
    const result = await screenCaptures.startRecording(caller, found.owner.runId, input.title, input.maxSeconds, request.signal)
    return 'error' in result ? captureFailure(result) : captureJson({ action: input.action, ...result })
  }
  const result = await screenCaptures.stopRecording(caller, found.owner.runId)
  return 'error' in result ? captureFailure(result) : captureJson({ action: input.action, capture: result })
}

export const POST = withDeviceRoute(handlePOST)

